/**
 * @file src/tableau/sparse-simplex.ts
 * @description Sparse simplex algorithm for large LP problems
 *
 * Optimized simplex implementation that operates directly on SparseMatrix
 * storage. Converts the dense tableau to CSC format, solves, and converts
 * back for solution extraction.
 *
 * Provides significant speedup for large, sparse problems where most
 * coefficients are zero.
 */
import type Tableau from "./tableau";
/**
 * Convert dense tableau to sparse and solve
 */
export declare function sparseSimplex(this: Tableau): Tableau;
/**
 * Threshold for using sparse (total cells)
 * Currently disabled - CSC format overhead exceeds benefits.
 * A dual-indexed (CSC+CSR) approach would be needed for efficient sparse simplex.
 */
export declare const SPARSE_THRESHOLD: number;
/**
 * Density threshold - only use sparse if below this density
 */
export declare const DENSITY_THRESHOLD = 0.1;
/**
 * Check if sparse mode should be used for this tableau
 */
export declare function shouldUseSparse(tableau: Tableau): boolean;
